if mibBuilder.loadTexts: asppPortRole.setStatus('current')
if mibBuilder.loadTexts: asppPortRole.setDescription("Specifies the router's protocol role. \n                 primary(1) - Indicates we are attaching to the terminal\n                              or alarm panel. \n                 secondary(2) - Indicates we are attaching to the host \n                                or alarm console..")
asppPortReceiveInterFrameTimeout = MibTableColumn((1, 3, 6, 1, 4, 1, 9, 9, 55, 1, 1, 1, 1, 3), Integer32().subtype(subtypeSpec=ValueRangeConstraint(0, 1000))).setUnits('milliseconds').setMaxAccess("readonly")
if mibBuilder.loadTexts: asppPortReceiveInterFrameTimeout.setStatus('current')
if mibBuilder.loadTexts: asppPortReceiveInterFrameTimeout.setDescription('Specifies the receive inter-frame-timeout period, used\n                 to delimit frames. Since all the protocols are\n                 implemented over RS-232 3-wire circuits (ie TX, RX and\n                 GND), the only general method for start-end frame \n                 detection is to monitor the time between received \n                 characters. If this time period exceeds the inter-frame\n                 timeout value, then frame end-start is detected.')
asppPortDeviceAddressOffset = MibTableColumn((1, 3, 6, 1, 4, 1, 9, 9, 55, 1, 1, 1, 1, 4), Integer32().subtype(subtypeSpec=ValueRangeConstraint(0, 255))).setUnits('bytes').setMaxAccess("readonly")
